[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ClipCast — One video is worth a thousand words</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --blue: #1868DB;
      --orange: #FF613D;
      --dark: #292A2E;
      --gray: #6B7280;
      --light-gray: #F3F4F6;
      --border: #E5E7EB;
      --white: #FFFFFF;
      --purple: #7C3AED;
      --indigo: #4F46E5;
    }
    body { font-family: 'Inter', sans-serif; color: var(--dark); background: var(--white); line-height: 1.6; }
    a { text-decoration: none; color: inherit; }
    img { max-width: 100%; }

    /* NAV */
    nav {
      position: sticky; top: 0; z-index: 100;
      background: rgba(255,255,255,0.95); backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
      padding: 0 2rem;
      display: flex; align-items: center; justify-content: space-between;
      height: 64px;
    }
    .nav-logo { font-size: 1.4rem; font-weight: 800; color: var(--blue); letter-spacing: -0.5px; }
    .nav-logo span { color: var(--orange); }
    .nav-links { display: flex; align-items: center; gap: 2rem; }
    .nav-links a { font-size: 0.9rem; font-weight: 500; color: var(--gray); transition: color 0.2s; }
    .nav-links a:hover { color: var(--dark); }
    .nav-actions { display: flex; align-items: center; gap: 1rem; }
    .btn { display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.6rem 1.4rem; border-radius: 8px; font-size: 0.9rem; font-weight: 600; cursor: pointer; transition: all 0.2s; border: none; }
    .btn-ghost { background: transparent; color: var(--gray); }
    .btn-ghost:hover { color: var(--dark); background: var(--light-gray); }
    .btn-primary { background: var(--blue); color: white; }
    .btn-primary:hover { background: #1559c0; transform: translateY(-1px); box-shadow: 0 4px 12px rgba(24,104,219,0.3); }
    .btn-orange { background: var(--orange); color: white; }
    .btn-orange:hover { background: #e5522e; transform: translateY(-1px); box-shadow: 0 4px 12px rgba(255,97,61,0.3); }
    .btn-outline { background: transparent; color: var(--blue); border: 2px solid var(--blue); }
    .btn-outline:hover { background: var(--blue); color: white; }
    .btn-lg { padding: 0.875rem 2rem; font-size: 1rem; border-radius: 10px; }

    /* HERO */
    .hero {
      background: linear-gradient(135deg, #EEF4FF 0%, #F5F0FF 50%, #FFF5F0 100%);
      padding: 6rem 2rem 4rem;
      text-align: center;
    }
    .hero-badge { display: inline-flex; align-items: center; gap: 0.5rem; background: white; border: 1px solid var(--border); border-radius: 100px; padding: 0.4rem 1rem; font-size: 0.8rem; font-weight: 600; color: var(--purple); margin-bottom: 2rem; box-shadow: 0 2px 8px rgba(0,0,0,0.06); }
    .hero h1 { font-size: clamp(2.5rem, 6vw, 4.5rem); font-weight: 900; line-height: 1.08; letter-spacing: -2px; color: var(--dark); max-width: 800px; margin: 0 auto 1.5rem; }
    .hero h1 .accent { color: var(--blue); }
    .hero p { font-size: 1.2rem; color: var(--gray); max-width: 560px; margin: 0 auto 2.5rem; line-height: 1.7; }
    .hero-ctas { display: flex; align-items: center; justify-content: center; gap: 1rem; flex-wrap: wrap; }
    .hero-mockup { margin-top: 4rem; max-width: 900px; margin-left: auto; margin-right: auto; background: white; border-radius: 16px; box-shadow: 0 24px 80px rgba(0,0,0,0.12); overflow: hidden; aspect-ratio: 16/9; display: flex; align-items: center; justify-content: center; border: 1px solid var(--border); }
    .mockup-placeholder { display: flex; flex-direction: column; align-items: center; gap: 1rem; color: var(--gray); }
    .play-btn { width: 72px; height: 72px; background: var(--blue); border-radius: 50%; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: transform 0.2s; }
    .play-btn:hover { transform: scale(1.1); }
    .play-btn svg { width: 28px; height: 28px; fill: white; }

    /* LOGO BAR */
    .logo-bar { padding: 3rem 2rem; background: white; border-bottom: 1px solid var(--border); text-align: center; }
    .logo-bar p { font-size: 0.85rem; font-weight: 600; color: var(--gray); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 2rem; }
    .logo-row { display: flex; align-items: center; justify-content: center; gap: 3rem; flex-wrap: wrap; }
    .logo-item { font-size: 1.1rem; font-weight: 700; color: #9CA3AF; letter-spacing: -0.5px; }

    /* SECTIONS */
    section { padding: 5rem 2rem; }
    .container { max-width: 1100px; margin: 0 auto; }
    .section-label { display: inline-flex; align-items: center; gap: 0.5rem; background: #EEF4FF; color: var(--blue); font-size: 0.78rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; padding: 0.35rem 0.9rem; border-radius: 100px; margin-bottom: 1.25rem; }
    .section-label.orange { background: #FFF1EE; color: var(--orange); }
    .section-label.purple { background: #F5F0FF; color: var(--purple); }
    h2 { font-size: clamp(1.8rem, 4vw, 3rem); font-weight: 800; letter-spacing: -1px; line-height: 1.15; color: var(--dark); }
    h3 { font-size: 1.15rem; font-weight: 700; color: var(--dark); }
    p.lead { font-size: 1.1rem; color: var(--gray); line-height: 1.7; margin-top: 0.75rem; }

    /* FEATURE HIGHLIGHT */
    .feature-highlight { background: #F8F9FF; }
    .fh-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
    .fh-visual { background: linear-gradient(135deg, #EEF4FF, #E0E7FF); border-radius: 16px; aspect-ratio: 4/3; display: flex; align-items: center; justify-content: center; font-size: 3rem; }
    .fh-content .badge { display: inline-flex; align-items: center; gap: 0.4rem; background: #FF613D; color: white; font-size: 0.7rem; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; padding: 0.2rem 0.6rem; border-radius: 4px; margin-bottom: 1rem; }

    /* SCREEN RECORDER */
    .screen-recorder { background: white; }
    .sr-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
    .sr-visual { background: linear-gradient(135deg, #E0E7FF, #EDE9FE); border-radius: 16px; aspect-ratio: 4/3; display: flex; align-items: center; justify-content: center; font-size: 3rem; }

    /* VIDEO EDITOR */
    .video-editor { background: var(--dark); color: white; }
    .video-editor h2 { color: white; }
    .video-editor .lead { color: #9CA3AF; }
    .ve-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-top: 3rem; }
    .ve-card { background: rgba(255,255,255,0.07); border: 1px solid rgba(255,255,255,0.1); border-radius: 12px; padding: 1.5rem; }
    .ve-card h3 { color: white; margin-bottom: 0.5rem; }
    .ve-card p { color: #9CA3AF; font-size: 0.9rem; line-height: 1.6; }
    .ve-icon { font-size: 1.8rem; margin-bottom: 1rem; }

    /* INTEGRATIONS */
    .integrations { background: white; text-align: center; }
    .integrations h2 { margin-bottom: 0.75rem; }
    .int-grid { display: flex; align-items: center; justify-content: center; gap: 1.5rem; flex-wrap: wrap; margin-top: 2.5rem; }
    .int-pill { display: flex; align-items: center; gap: 0.6rem; background: var(--light-gray); border-radius: 100px; padding: 0.5rem 1.2rem; font-weight: 600; font-size: 0.9rem; }
    .int-pill span.dot { width: 24px; height: 24px; border-radius: 50%; display: inline-block; }

    /* ENGAGEMENT */
    .engagement { background: #F8F9FF; }
    .eng-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
    .eng-stats { display: flex; flex-direction: column; gap: 1.5rem; margin-top: 2rem; }
    .stat-item { display: flex; align-items: center; gap: 1rem; }
    .stat-num { font-size: 2.5rem; font-weight: 900; color: var(--blue); letter-spacing: -1px; min-width: 80px; }
    .stat-text { color: var(--gray); font-size: 0.95rem; }

    /* SECURITY */
    .security { background: white; }
    .sec-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
    .sec-list { list-style: none; display: flex; flex-direction: column; gap: 1rem; margin-top: 1.5rem; }
    .sec-list li { display: flex; align-items: flex-start; gap: 0.75rem; font-size: 0.95rem; color: var(--gray); }
    .sec-list li::before { content: '✓'; color: var(--blue); font-weight: 700; flex-shrink: 0; margin-top: 0.1rem; }
    .sec-visual { background: linear-gradient(135deg, #EEF4FF, #DBEAFE); border-radius: 16px; aspect-ratio: 4/3; display: flex; align-items: center; justify-content: center; font-size: 3rem; }

    /* USE CASES */
    .use-cases { background: #F8F9FF; text-align: center; }
    .uc-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.5rem; margin-top: 3rem; }
    .uc-card { background: white; border: 1px solid var(--border); border-radius: 12px; padding: 2rem 1.5rem; text-align: left; transition: all 0.2s; cursor: pointer; }
    .uc-card:hover { border-color: var(--blue); box-shadow: 0 8px 24px rgba(24,104,219,0.1); transform: translateY(-3px); }
    .uc-icon { font-size: 2rem; margin-bottom: 1rem; }
    .uc-card h3 { margin-bottom: 0.5rem; }
    .uc-card p { font-size: 0.875rem; color: var(--gray); line-height: 1.6; }

    /* FEATURES GRID */
    .features-grid { background: white; text-align: center; }
    .fg-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.25rem; margin-top: 3rem; }
    .fg-card { background: var(--light-gray); border-radius: 10px; padding: 1.5rem; text-align: left; }
    .fg-icon { font-size: 1.5rem; margin-bottom: 0.75rem; }
    .fg-card p { font-size: 0.875rem; color: var(--dark); font-weight: 600; }

    /* BLOG */
    .blog { background: #F8F9FF; }
    .blog-inner { display: grid; grid-template-columns: repeat(2, 1fr); gap: 2rem; margin-top: 3rem; }
    .blog-card { background: white; border-radius: 12px; overflow: hidden; border: 1px solid var(--border); transition: all 0.2s; }
    .blog-card:hover { box-shadow: 0 8px 24px rgba(0,0,0,0.1); transform: translateY(-3px); }
    .blog-img { height: 180px; display: flex; align-items: center; justify-content: center; font-size: 2.5rem; }
    .blog-img.blue { background: linear-gradient(135deg, #EEF4FF, #DBEAFE); }
    .blog-img.purple { background: linear-gradient(135deg, #F5F0FF, #EDE9FE); }
    .blog-body { padding: 1.5rem; }
    .blog-body h3 { font-size: 1rem; line-height: 1.5; margin-bottom: 0.5rem; }
    .blog-body p { font-size: 0.875rem; color: var(--gray); line-height: 1.6; }

    /* ENTERPRISE CTA */
    .enterprise-cta { background: var(--dark); color: white; text-align: center; }
    .enterprise-cta h2 { color: white; margin-bottom: 0.75rem; }
    .enterprise-cta p { color: #9CA3AF; font-size: 1.1rem; margin-bottom: 2.5rem; }

    /* TESTIMONIALS */
    .testimonials { background: white; }
    .test-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-top: 3rem; }
    .test-card { background: var(--light-gray); border-radius: 12px; padding: 1.5rem; }
    .test-card blockquote { font-size: 0.9rem; color: var(--gray); line-height: 1.7; margin-bottom: 1.25rem; font-style: italic; }
    .test-author { display: flex; align-items: center; gap: 0.75rem; }
    .author-avatar { width: 40px; height: 40px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.85rem; color: white; flex-shrink: 0; }
    .author-name { font-weight: 700; font-size: 0.875rem; }
    .author-role { font-size: 0.8rem; color: var(--gray); }

    /* CTA BANNER */
    .cta-banner { background: linear-gradient(135deg, var(--blue) 0%, #4F46E5 100%); color: white; text-align: center; padding: 5rem 2rem; }
    .cta-banner h2 { color: white; font-size: clamp(2rem, 4vw, 3rem); margin-bottom: 0.75rem; }
    .cta-banner p { color: rgba(255,255,255,0.8); margin-bottom: 2.5rem; font-size: 1.1rem; }
    .cta-banner .btn-white { background: white; color: var(--blue); font-weight: 700; }
    .cta-banner .btn-white:hover { background: #F0F5FF; transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.2); }

    /* FOOTER */
    footer { background: var(--dark); color: white; padding: 4rem 2rem 2rem; }
    .footer-top { display: grid; grid-template-columns: 2fr repeat(5, 1fr); gap: 2rem; margin-bottom: 3rem; }
    .footer-brand .nav-logo { font-size: 1.3rem; margin-bottom: 1rem; display: block; }
    .footer-brand p { font-size: 0.85rem; color: #9CA3AF; line-height: 1.7; }
    .footer-col h4 { font-size: 0.8rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: #6B7280; margin-bottom: 1rem; }
    .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 0.6rem; }
    .footer-col ul li a { font-size: 0.85rem; color: #9CA3AF; transition: color 0.2s; }
    .footer-col ul li a:hover { color: white; }
    .footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 2rem; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 1rem; }
    .footer-bottom p { font-size: 0.8rem; color: #6B7280; }

    /* COOKIE BANNER */
    .cookie-banner {
      position: fixed; bottom: 0; left: 0; right: 0; z-index: 999;
      background: white; border-top: 1px solid var(--border);
      box-shadow: 0 -4px 24px rgba(0,0,0,0.1);
      padding: 1.25rem 2rem;
      display: flex; align-items: center; justify-content: space-between; gap: 1.5rem; flex-wrap: wrap;
    }
    .cookie-banner p { font-size: 0.875rem; color: var(--gray); max-width: 600px; }
    .cookie-banner p a { color: var(--blue); }
    .cookie-actions { display: flex; gap: 0.75rem; flex-shrink: 0; flex-wrap: wrap; }
    .btn-sm { padding: 0.5rem 1rem; font-size: 0.85rem; border-radius: 8px; }

    /* COOKIE MODAL */
    .modal-overlay {
      position: fixed; inset: 0; z-index: 1000;
      background: rgba(0,0,0,0.5); display: flex; align-items: center; justify-content: center; padding: 1rem;
      opacity: 0; pointer-events: none; transition: opacity 0.2s;
    }
    .modal-overlay.open { opacity: 1; pointer-events: all; }
    .modal { background: white; border-radius: 16px; padding: 2rem; max-width: 480px; width: 100%; }
    .modal h3 { font-size: 1.2rem; margin-bottom: 0.5rem; }
    .modal p { font-size: 0.875rem; color: var(--gray); margin-bottom: 1.5rem; }
    .toggle-row { display: flex; align-items: center; justify-content: space-between; padding: 1rem 0; border-bottom: 1px solid var(--border); }
    .toggle-row:last-of-type { border-bottom: none; }
    .toggle-label { font-size: 0.9rem; font-weight: 600; }
    .toggle-desc { font-size: 0.8rem; color: var(--gray); }
    .toggle-switch { position: relative; width: 48px; height: 26px; flex-shrink: 0; }
    .toggle-switch input { opacity: 0; width: 0; height: 0; }
    .toggle-track { position: absolute; inset: 0; background: #D1D5DB; border-radius: 100px; cursor: pointer; transition: background 0.2s; }
    .toggle-switch input:checked + .toggle-track { background: var(--blue); }
    .toggle-track::after { content: ''; position: absolute; width: 20px; height: 20px; background: white; border-radius: 50%; top: 3px; left: 3px; transition: transform 0.2s; }
    .toggle-switch input:checked + .toggle-track::after { transform: translateX(22px); }
    .modal-footer { display: flex; gap: 0.75rem; margin-top: 1.5rem; }

    @media (max-width: 768px) {
      .fh-inner, .sr-inner, .sec-inner, .eng-inner { grid-template-columns: 1fr; }
      .ve-grid, .uc-grid { grid-template-columns: 1fr 1fr; }
      .fg-grid { grid-template-columns: 1fr 1fr; }
      .test-grid { grid-template-columns: 1fr; }
      .blog-inner { grid-template-columns: 1fr; }
      .footer-top { grid-template-columns: 1fr 1fr; }
      nav .nav-links { display: none; }
    }
  </style>
</head>
