  const monthlyLabel = document.getElementById('monthlyLabel');
  const annualLabel = document.getElementById('annualLabel');

  function updatePrices() {
    const isAnnual = billingToggle.checked;
    const key = isAnnual ? 'annual' : 'monthly';
    const note = isAnnual ? 'per user / month, billed annually' : 'per user / month, billed monthly';

    document.getElementById('price-business').textContent = '$' + prices[key].business;
    document.getElementById('price-ai').textContent = '$' + prices[key].ai;
    document.getElementById('note-business').textContent = note;
    document.getElementById('note-ai').textContent = note;
    document.getElementById('th-business').textContent = '$' + prices[key].business;
    document.getElementById('th-ai').textContent = '$' + prices[key].ai;

    monthlyLabel.classList.toggle('active', !isAnnual);
    annualLabel.style.fontWeight = isAnnual ? '700' : '500';
    annualLabel.style.color = isAnnual ? 'var(--dark)' : 'var(--gray)';
  }

  billingToggle.addEventListener('change', updatePrices);

  // Slider
  const slider = document.getElementById('teamSlider');
  const sliderVal = document.getElementById('sliderVal');
  function updateSlider() {
    const val = parseInt(slider.value);
    sliderVal.textContent = val === 1 ? '1 member' : (val >= 200 ? '200+ members' : val + ' members');
    const pct = ((val - 1) / (200 - 1)) * 100;
    slider.style.setProperty('--range-pct', pct + '%');
    // Suggest enterprise for large teams
    const enterpriseCard = document.querySelector('.plan-card:last-child');
    if (val >= 50) {
      enterpriseCard.style.borderColor = 'var(--orange)';
    } else {
      enterpriseCard.style.borderColor = 'var(--border)';
    }
  }
  slider.addEventListener('input', updateSlider);
  updateSlider();

